import pytest

from bedrock_protocol import v1001, v2168, v2225

versions = [v1001, v2168, v2225]

# generated by gophertunnel b8bd735 and again at 6353c49:
# packet.ServerBoundLoadingScreen{Type: 1, LoadingScreenID: protocol.Option[uint32](9)}
LOADING = bytes.fromhex("020109000000")

# generated by gophertunnel b8bd735 and again at 6353c49:
# packet.ServerBoundLoadingScreen{Type: 2}
ABSENT = bytes.fromhex("0400")

GOLDENS = [
    pytest.param(
        v.ServerboundLoadingScreenPacket(
            loading_screen_packet_type=v.ServerboundLoadingScreenPacketType.START_LOADING_SCREEN, loading_screen_id=9
        ),
        LOADING,
        id=f"{v.__name__.rpartition('.')[2]}-with-screen-id",
    )
    for v in versions
] + [
    pytest.param(
        v.ServerboundLoadingScreenPacket(
            loading_screen_packet_type=v.ServerboundLoadingScreenPacketType.END_LOADING_SCREEN
        ),
        ABSENT,
        id=f"{v.__name__.rpartition('.')[2]}-without-screen-id",
    )
    for v in versions
]


@pytest.mark.parametrize("version", versions)
def test_serverbound_loading_screen_is_packet_312(version):
    assert version.packets[312] is version.ServerboundLoadingScreenPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_serverbound_loading_screen_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_serverbound_loading_screen_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
